/* ===== Dead Town · música de guerra para asaltos de banda (pista original sintetizada, licencia CC0) ===== */
(function(){
'use strict';
const B64="";
let buf=null,src=null,gain=null,loading=false,want=false;
const vol=()=>{try{return (typeof musicVol==='number'?musicVol:.34)*(MUSIC?1:0)}catch(e){return .3}};
function load(ac,cb){if(buf)return cb();if(loading)return;loading=true;const bin=atob(B64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
 ac.decodeAudioData(u.buffer,b=>{buf=b;loading=false;cb()},()=>{loading=false})}
function start(ac){if(src)return;src=ac.createBufferSource();src.buffer=buf;src.loop=true;gain=ac.createGain();gain.gain.value=0;src.connect(gain);gain.connect(ac.destination);src.start();gain.gain.setTargetAtTime(Math.min(1,vol()*2.2),ac.currentTime,1.2)}
window.warMusic={play(ac){if(!ac||vol()<=0)return false;want=true;if(buf)start(ac);else load(ac,()=>{if(want)start(ac)});return true},
 stop(ac){want=false;if(!src)return;const s=src,g=gain;src=null;gain=null;try{g.gain.setTargetAtTime(0,(ac||s.context).currentTime,.6)}catch(e){}setTimeout(()=>{try{s.stop()}catch(e){}try{s.disconnect();g.disconnect()}catch(e){}},2500)},
 vol(ac){if(gain&&ac)gain.gain.setTargetAtTime(Math.min(1,vol()*2.2),ac.currentTime,.3)}};
setInterval(()=>{try{const ac=(typeof AC!=='undefined'&&AC)?AC:null;if(ac)warMusic.vol(ac)}catch(e){}},1000);
})();
